Here’s a simple POSIX-threads target function that blocks forever on a synchronization primitive (a condition variable), without consuming CPU:

```c
#include <pthread.h>

static pthread_mutex_t g_mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t  g_cv  = PTHREAD_COND_INITIALIZER;

void *thread_wait_forever(void *arg)
{
    (void)arg;

    pthread_mutex_lock(&g_mtx);
    for (;;) {
        // Wait forever until someone signals/broadcasts g_cv.
        // Even if signaled spuriously, the loop re-waits.
        pthread_cond_wait(&g_cv, &g_mtx);
    }
    // Unreachable:
    // pthread_mutex_unlock(&g_mtx);
    // return NULL;
}
```

Alternative if you want “wait forever” with a semaphore instead:

```c
#include <semaphore.h>

extern sem_t g_sem;

void *thread_wait_forever_sem(void *arg)
{
    (void)arg;
    for (;;) sem_wait(&g_sem);
}
```

```c
// gcc -O2 -pthread thread_stress.c -o thread_stress
#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

static pthread_mutex_t g_mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t  g_cv  = PTHREAD_COND_INITIALIZER;

static void *thread_wait_forever(void *arg) {
    (void)arg;
    pthread_mutex_lock(&g_mtx);
    for (;;) pthread_cond_wait(&g_cv, &g_mtx);
    return NULL;
}

int main(void) {
    size_t n = 0;

    for (;;) {
        pthread_t t;
        int rc = pthread_create(&t, NULL, thread_wait_forever, NULL);
        if (rc != 0) {
            fprintf(stderr, "pthread_create failed at n=%zu: %s (rc=%d)\n",
                    n, strerror(rc), rc);
            break;
        }

        // Keep threads around (don’t join); detach so we don’t leak join handles.
        pthread_detach(t);

        n++;
        if ((n % 1000) == 0) {
            fprintf(stderr, "created %zu threads...\n", n);
        }
    }

    fprintf(stderr, "total created: %zu\n", n);
    return 0;
}
```

This keeps each thread blocked forever on a condition variable, then loops creating more until `pthread_create` fails (e.g., `EAGAIN` / `ENOMEM` / `EPERM` depending on which limit you hit).

```c
// gcc -O2 -pthread thread_stress.c -o thread_stress
#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static pthread_mutex_t g_mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t  g_cv  = PTHREAD_COND_INITIALIZER;

static void *thread_wait_forever(void *arg) {
    (void)arg;
    pthread_mutex_lock(&g_mtx);
    for (;;) pthread_cond_wait(&g_cv, &g_mtx);
    return NULL;
}

int main(void) {
    size_t cap = 1024;
    size_t n = 0;
    pthread_t *threads = malloc(cap * sizeof(*threads));
    if (!threads) {
        perror("malloc");
        return 1;
    }

    for (;;) {
        if (n == cap) {
            cap *= 2;
            pthread_t *tmp = realloc(threads, cap * sizeof(*threads));
            if (!tmp) {
                fprintf(stderr, "realloc failed at n=%zu\n", n);
                break;
            }
            threads = tmp;
        }

        int rc = pthread_create(&threads[n], NULL, thread_wait_forever, NULL);
        if (rc != 0) {
            fprintf(stderr, "pthread_create failed at n=%zu: %s (rc=%d)\n",
                    n, strerror(rc), rc);
            break;
        }

        n++;
        if ((n % 1000) == 0) fprintf(stderr, "created %zu threads...\n", n);
    }

    fprintf(stderr, "total created: %zu\n", n);

    // Keep process alive so all created threads remain active/in-memory.
    pause();
    return 0;
}
```

Notes:
- This stores every `pthread_t` in a growable heap array (persistent for process lifetime).
- Threads are *not* detached; they remain joinable (resources held) and handles remain valid.
- `pause()` keeps the process running so threads stay alive.
